explain (analyze,buffers,format json) select cast(p.id as text) from pedido p join etapa_pedido e on e.pedido_id = p.id and e.estado = 'ACTUAL' join definicion_etapa d on d.flujo_id = p.flujo_id and d.numero = e.numero where not p.finalizado and (cast(true as boolean) or (d.rol_codigo in ('admin') and (e.asignado_a is null or e.asignado_a = '21232f29-7a57-35a7-8389-4a0e4a801fc3'::uuid))) order by p.creado_en desc, p.id limit 20 offset 0;
explain (analyze,buffers,format json) select cast(p.id as text) from pedido p join etapa_pedido e on e.pedido_id = p.id and e.estado = 'ACTUAL' join definicion_etapa d on d.flujo_id = p.flujo_id and d.numero = e.numero where not p.finalizado and (cast(false as boolean) or (d.rol_codigo in ('logistica') and (e.asignado_a is null or e.asignado_a = 'e9a5390f-6e43-3dc5-949b-b582def8a540'::uuid))) order by p.creado_en desc, p.id limit 20 offset 0;
explain (analyze,buffers,format json) select id from pedido where numero='DK-EC-2026-0008';
explain (analyze,buffers,format json) select id from pedido where lower(numero) like '%ficticio%' escape '!' or lower(nombre) like '%ficticio%' escape '!' order by creado_en desc,id limit 20;